(function(root){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields={math:'수학',physics:'물리',chemistry:'화학',biology:'생명과학',earth:'지구과학',ai:'정보',language:'언어',research:'연구',liberal:'융합·교양',design:'자율설계'};
const categories={specialist:'전문선택',liberal:'융합·교양',design:'학생자율설계'};
const termName=t=>`${Math.floor(t/2)+1}학년 ${t%2+1}학기`;
function create(E){
 function progress(s){const c=E.getCurriculumStatus(s);return `<section class="curriculum-progress">${c.requirements.map(r=>`<div class="card credit-card ${r.complete?'complete':''}"><small>${esc(r.label)}</small><strong>${r.current}<span> / ${r.required}학점</span></strong><div class="credit-track"><span style="width:${Math.min(100,r.current/r.required*100)}%"></span></div><p>${r.complete?'이수 기준 충족':`${Math.max(0,r.required-r.current)}학점 더 이수해야 해요`}</p></div>`).join('')}</section>${c.legacyExempt?'<p class="notice">이전 버전에서 졸업한 기록은 그대로 인정됩니다.</p>':''}`;}
 function majorCards(s){const ms=E.getMajorOptions(s);return `<div class="section-title academic-section-title"><h2>수업에서 이어지는 전공</h2><span class="tag">${ms.filter(m=>m.unlocked).length}개 지원 가능</span></div><p class="section-description">이수 완료한 선택과목이 지원할 수 있는 희망 전공을 넓혀요. F 과목과 아직 수강 중인 과목은 조건에 포함하지 않습니다.</p><div class="major-grid">${ms.map(m=>`<article class="card major-card ${m.unlocked?'unlocked':'locked'}"><div class="row"><h3>${esc(m.name)}</h3><span class="major-state">${m.unlocked?'지원 가능':'준비 중'}</span></div><p>${esc(m.description)}</p><div class="major-rule">${esc(m.requirementsText)}</div><small>${m.unlocked?'과목 이수 조건 충족':esc((m.missing||[]).join(' · '))}</small></article>`).join('')}</div><p class="academic-disclaimer">전공별 학점 조건은 이 게임의 규칙입니다. 대학의 실제 모집단위·필수 이수 조건을 뜻하지 않으며, 과학기술원은 희망 전공을 선택하는 방식으로 표현했어요.</p>`;}
 function catalogue(s,ids){const o=E.getEnrollmentOptions(s),sel=new Set(ids);return `<div class="enrollment-layout"><div><div class="recommend-label">관심 분야로 시간표 초안 만들기</div><div class="recommend-buttons">${Object.entries(fields).filter(([id])=>['math','physics','chemistry','biology','earth','ai'].includes(id)).map(([id,n])=>`<button type="button" class="secondary" data-recommend="${id}">${n} 중심</button>`).join('')}<button type="button" class="plain-button" data-clear-courses>선택 비우기</button></div><p class="form-hint">추천을 누르면 초안이 채워져요. 과목을 바꾼 뒤 직접 확정하세요.</p>${['specialist','liberal','design'].map(cat=>{const list=o.courses.filter(c=>c.category===cat);if(!list.length)return '';return `<section class="course-group"><div class="section-title"><h3>${categories[cat]}</h3><span>${cat==='specialist'?'이번 학기 6~16학점':cat==='liberal'?'이번 학기 0~4학점':'이번 학기 3학점'}</span></div><div class="course-grid">${list.map(c=>`<label class="course-choice ${sel.has(c.id)?'selected':''}"><input type="checkbox" name="course" value="${esc(c.id)}" ${sel.has(c.id)?'checked':''}><div><small>${fields[c.field]||categories[cat]} · ${c.credits}학점${c.difficulty?` · 난도 ${c.difficulty}`:''}</small><strong>${esc(c.name)}</strong>${c.description?`<p>${esc(c.description)}</p>`:''}${(c.gameOnly||c.source?.includes('게임'))?'<em>게임 내 개설</em>':''}</div></label>`).join('')}</div></section>`;}).join('')}</div><aside class="enrollment-cart"><div id="enrollment-summary">${selectionSummary(s,ids)}</div><button class="primary" data-do="enroll" ${E.validateEnrollment(s,ids).valid?'':'disabled'}>이 시간표로 수강 확정</button><small>확정한 시간표는 이번 학기 동안 유지돼요.</small></aside></div><details class="mini-details"><summary>필수 수업과 수강 규칙</summary><p>필수 수업: ${(o.requiredCourses||[]).map(c=>`${esc(c.name)} ${c.credits}학점`).join(' · ')}</p>${(o.notes||[]).map(n=>`<p>${esc(n)}</p>`).join('')}<p>학기별 선택 범위와 자율설계의 3학점씩 배분은 게임 진행을 위한 설정입니다.</p></details>`;}
 function selectionSummary(s,ids){const o=E.getEnrollmentOptions(s),chosen=o.courses.filter(c=>ids.includes(c.id)),v=E.validateEnrollment(s,ids);const sum=cat=>chosen.filter(c=>c.category===cat).reduce((n,c)=>n+c.credits,0);const creditsByField=chosen.filter(c=>c.category==='specialist').reduce((a,c)=>{a[c.field]=(a[c.field]||0)+c.credits;return a;},{});const projected=E.getMajorOptions(s).filter(m=>m.id!=='general'&&Object.entries(m.requirements||{}).every(([f,n])=>(creditsByField[f]||0)>=n));return `<span class="eyebrow">MY SEMESTER</span><h3>이번 학기 시간표</h3><strong class="cart-total">${chosen.reduce((n,c)=>n+c.credits,0)}<small>선택학점 · ${chosen.length}과목</small></strong>${Object.entries(categories).map(([id,n])=>`<div class="cart-line"><span>${n}</span><b>${sum(id)}</b></div>`).join('')}<div class="course-errors" role="status">${v.valid?'<p class="valid">수강신청을 확정할 수 있어요.</p>':v.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>${o.term===3?`<div class="course-future-preview"><b>모두 이수하면 열리는 전공</b><p>${projected.length?projected.map(m=>esc(m.name)).join(' · '):'전문선택 과목을 골라 전공 경로를 확인하세요.'}</p><small>미리보기 · 실제 지원은 학기 성적 확정 후 가능</small></div>`:''}<p class="cart-help">많은 과목을 들으면 배움이 넓어지고 주간 학업 부담도 늘어요.</p>`;}
 function currentPlan(s){const c=E.getCurriculumStatus(s);return `<section class="card course-current"><div class="section-title"><h2>${s.turn<24?'선택과목은 2학년 2학기부터':s.turn>=48?'나의 수강 기록':'이번 학기의 수업'}</h2><span class="tag">SEMESTER PLAN</span></div>${s.turn<24?'<p>아래 전공 조건을 보며 관심 분야를 정해보세요. 수강신청은 학기 시작에 열립니다.</p>':`<div class="subject-pills">${(c.currentSubjects||[]).map(x=>`<span>${esc(x.name)} <b>${x.credits}학점</b></span>`).join('')}</div>`}<p class="section-description">전문선택 28학점, 융합·교양 4학점, 학생자율설계 6학점을 누적해요. 이 세 영역의 학점은 TOEIC·현장연구 요건과 함께 졸업에 반영됩니다.</p>${c.plans&&Object.keys(c.plans).length?`<details class="mini-details"><summary>학기별 수강 기록</summary>${Object.entries(c.plans).map(([t,p])=>`<div class="plan-history"><b>${termName(Number(p.term??t))}</b><p>${(p.subjects||p.courses||[]).map(x=>esc(x.name)).join(' · ')||esc(p.names?.join(' · ')||'확정된 시간표')}</p></div>`).join('')}</details>`:''}${(c.notes||[]).map(n=>`<p class="notice">${esc(n)}</p>`).join('')}${c.legacyEquivalences?.length?`<details class="mini-details"><summary>이전 기록의 학점 인정 내역</summary>${c.legacyEquivalences.map(e=>`<div class="plan-history"><b>${termName(e.term)}</b><p>${esc(e.basis)}<br>전문선택 ${e.earned.specialist} · 융합·교양 ${e.earned.liberal} · 자율설계 ${e.earned.design}학점 인정</p></div>`).join('')}</details>`:''}${c.makeups?.length?`<details class="mini-details"><summary>보완 이수 기록</summary>${c.makeups.map(m=>`<p>${esc(m.name)} · ${m.credits}학점 · P</p>`).join('')}</details>`:''}</section>`;}
 function makeup(s){if(s.turn<48||!s.alive)return '';const opts=E.getCourseMakeupOptions(s);if(!opts.length)return '';return `<section class="card course-makeup"><h3>부족한 선택학점 보완하기</h3><p>보완 과목을 한 주씩 이수해 남은 졸업요건을 채워요. 기존 성적표는 그대로 남습니다.</p><label class="field">보완할 과목<select id="makeup-course">${opts.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${categories[c.category]||''} ${c.credits}학점</option>`).join('')}</select></label><button class="primary" data-do="course-makeup">한 주 보완 수업 듣기</button></section>`;}
 return {progress,majorCards,catalogue,selectionSummary,currentPlan,makeup};
}
root.GSAAcademicUI={create};
})(window);
